/* QUIZINOX learning suite — Notes, Knowledge Vault, Roadmaps, Teacher, Discussion and Content Studio. */
let notesFolder = null;
let activeNote = null;
let creatorSource = { name: 'Pasted source', text: '' };
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const uid = () => crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const dateKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today = () => dateKey();
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = d => d ? new Date(`${d}T00:00:00`).toLocaleDateString(undefined, { day:'numeric', month:'short', year:'numeric' }) : 'No date';
const dayDiff = d => Math.ceil((new Date(`${d}T23:59:59`).getTime() - Date.now()) / 86400000);
const arrays = db => {
  for (const k of ['notes','vault','roadmaps','teacherSessions','discussions','creatorOutputs']) if (!Array.isArray(db[k])) db[k] = [];
};
function shell(view, eyebrow, title, desc, actions = '') {
  view.innerHTML = `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="title-actions">${actions}</div></div>`;
}
function panel(title, subtitle, body, extra = '') {
  return `<section class="panel l-panel ${extra}"><div class="panel-head"><div><h3>${title}</h3>${subtitle ? `<p>${subtitle}</p>` : ''}</div></div>${body}</section>`;
}
function fileRead(file) { return new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(r.result); r.onerror = () => reject(r.error); r.readAsDataURL(file); }); }
function addTo(db, key, item, ctx) { arrays(db); db[key].unshift(item); ctx.save(); }
function aiError(ctx, e) { ctx.toast(`AI: ${e?.message || 'Request failed'}`, 5000); }

export function renderLearningPage(view, tab, ctx) {
  arrays(ctx.db);
  const pages = {
    notes: () => renderNotes(view, ctx),
    vault: () => renderVault(view, ctx),
    roadmap: () => renderRoadmaps(view, ctx),
    teacher: () => renderTeacher(view, ctx),
    discussion: () => renderDiscussion(view, ctx),
    creator: () => renderCreator(view, ctx),
  };
  (pages[tab] || pages.notes)();
}

/* -------------------------------- NOTES -------------------------------- */
function renderNotes(view, ctx) {
  arrays(ctx.db);
  const db = ctx.db;
  if (notesFolder && !db.notes.some(x => x.id === notesFolder && x.type === 'folder')) notesFolder = null;
  const folders = db.notes.filter(x => x.type === 'folder');
  const notes = db.notes.filter(x => x.type === 'note');
  if (activeNote && !notes.some(x => x.id === activeNote)) activeNote = null;
  const current = notes.find(x => x.id === activeNote) || null;
  const tree = parent => folders.filter(x => (x.parentId || null) === parent).map(f => `<div class="l-tree-node"><button class="l-tree-btn ${notesFolder === f.id ? 'active' : ''}" data-folder="${f.id}">📁 ${esc(f.title)} <small>${notes.filter(n => n.parentId === f.id).length}</small></button>${tree(f.id)}</div>`).join('');
  const folderNotes = notes.filter(n => notesFolder ? n.parentId === notesFolder : true).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));
  const actions = `<button class="secondary" id="noteFolderAdd">＋ Subsection</button><button class="primary" id="noteAdd">＋ New note</button>`;
  shell(view, 'PERSONAL STUDY WORKSPACE', 'Notes & notebooks', 'Paste anything, import PDFs or text, create nested subsections, and search across your own study material.', actions);
  view.innerHTML += `<div class="l-notes-layout"><aside class="panel l-folder-panel"><div class="l-folder-head"><b>My notebooks</b><button class="textbtn" id="rootFolderAdd">＋ Folder</button></div><button class="l-tree-btn ${notesFolder === null ? 'active' : ''}" data-folder="root">🗂 All notes <small>${notes.length}</small></button>${tree(null)}<div class="l-folder-foot">${folders.length} folders · ${notes.length} notes</div></aside><div class="l-notes-main">${panel('AI search your notes', 'Search locally, then ask AI to connect ideas from your saved material.', `<div class="l-inline-search"><input id="noteSearch" placeholder="Search a concept, keyword or question…"/><button class="primary" id="noteSearchBtn">⌕ Search</button></div><div id="noteSearchResult" class="l-search-results"></div>`)}<div class="l-notes-columns"><div class="panel l-note-list"><div class="panel-head"><div><h3>${notesFolder ? esc(folders.find(f=>f.id===notesFolder)?.title || 'Folder') : 'All notes'}</h3><p>Open a note to edit or continue writing</p></div></div>${folderNotes.length ? folderNotes.map(n=>`<button class="l-note-row ${n.id===activeNote?'active':''}" data-note="${n.id}"><span>📝</span><span><b>${esc(n.title || 'Untitled note')}</b><small>${esc((n.body||'').slice(0,90))}</small></span><time>${n.updatedAt ? new Date(n.updatedAt).toLocaleDateString() : ''}</time></button>`).join('') : '<div class="empty-mini"><b>No notes in this section</b><small>Create a note or import a PDF/TXT file.</small></div>'}</div><div class="panel l-note-editor" id="noteEditor">${current ? `<div class="l-editor-head"><span class="tag">${esc(folders.find(f=>f.id===current.parentId)?.title || 'Personal note')}</span><button class="textbtn danger-text" id="noteDelete">Delete</button></div><label>Note title<input id="noteTitle" value="${esc(current.title)}" placeholder="Give this note a title"/></label><label>Content<textarea id="noteBody" rows="16" placeholder="Paste notes, add explanations, facts, links…">${esc(current.body||'')}</textarea></label><label>Tags<input id="noteTags" value="${esc((current.tags||[]).join(', '))}" placeholder="Polity, Parliament, PYQ…"/></label><div class="l-actions"><button class="primary" id="noteSave">Save note</button><button class="secondary" id="noteVault">Save a copy to Knowledge Vault</button></div><small class="muted">${current.sourceName ? `Imported from ${esc(current.sourceName)} · ` : ''}Last saved ${current.updatedAt ? new Date(current.updatedAt).toLocaleString() : 'not yet'}</small>` : '<div class="l-editor-empty"><div>📝</div><b>Select a note or create a new one</b><small>Nested folders are unlimited. Notes remain stored on this device.</small><button class="primary" id="emptyNewNote">＋ Create note</button></div>'}</div></div></div></div><div class="l-import-strip panel"><div><b>Bring study material in</b><small>PDF, TXT or pasted text — PDF text extraction runs on your device.</small></div><button class="secondary" id="noteImport">⇧ Import PDF / TXT</button><input type="file" id="noteFile" accept=".pdf,.txt,.md,text/plain,application/pdf" hidden/><label class="l-url-import">URL <input id="noteUrl" placeholder="https://…"/><button class="secondary" id="noteUrlAdd">Import URL</button></label></div>`;
  $$('[data-folder]', view).forEach(b => b.onclick = () => { notesFolder = b.dataset.folder === 'root' ? null : b.dataset.folder; activeNote = null; renderNotes(view, ctx); });
  $$('[data-note]', view).forEach(b => b.onclick = () => { activeNote = b.dataset.note; renderNotes(view, ctx); });
  const addFolder = () => { const name = prompt('Name this folder / subsection:'); if (!name?.trim()) return; addTo(db,'notes',{id:uid(),type:'folder',title:name.trim(),parentId:notesFolder,createdAt:new Date().toISOString()},ctx); renderNotes(view,ctx); };
  $('#rootFolderAdd',view).onclick = () => { const name = prompt('Name this notebook:'); if (!name?.trim()) return; addTo(db,'notes',{id:uid(),type:'folder',title:name.trim(),parentId:null,createdAt:new Date().toISOString()},ctx); renderNotes(view,ctx); };
  $('#noteFolderAdd',view).onclick = addFolder;
  const newNote = () => { const n={id:uid(),type:'note',title:'New note',body:'',tags:[],parentId:notesFolder,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}; db.notes.unshift(n); activeNote=n.id; ctx.save(); renderNotes(view,ctx); $('#noteTitle',view)?.focus(); };
  $('#noteAdd',view).onclick = newNote; $('#emptyNewNote',view)?.addEventListener('click',newNote);
  $('#noteSave',view)?.addEventListener('click',()=>{const n=notes.find(x=>x.id===activeNote);if(!n)return;n.title=$('#noteTitle',view).value.trim()||'Untitled note';n.body=$('#noteBody',view).value;n.tags=$('#noteTags',view).value.split(',').map(x=>x.trim()).filter(Boolean);n.updatedAt=new Date().toISOString();ctx.save();ctx.toast('Note saved ✓');renderNotes(view,ctx);});
  $('#noteDelete',view)?.addEventListener('click',async()=>{if(!await ctx.confirmBox('Delete note?','This note will be removed from this device.','Delete',true))return;db.notes=db.notes.filter(x=>x.id!==activeNote);activeNote=null;ctx.save();renderNotes(view,ctx);});
  $('#noteVault',view)?.addEventListener('click',()=>{const n=notes.find(x=>x.id===activeNote);if(!n)return;addTo(db,'vault',{id:uid(),title:n.title,kind:'note',content:n.body,tags:n.tags||[],createdAt:new Date().toISOString(),source:`Notes · ${n.title}`},ctx);ctx.toast('Saved to Personal Knowledge Vault ✓');});
  $('#noteImport',view).onclick=()=>$('#noteFile',view).click();
  $('#noteFile',view).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{let body='';if(f.type==='application/pdf'||/\.pdf$/i.test(f.name))body=await ctx.pdfText(f);else body=await f.text();const n={id:uid(),type:'note',title:f.name.replace(/\.[^.]+$/,''),body,tags:['Imported'],parentId:notesFolder,sourceName:f.name,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};db.notes.unshift(n);activeNote=n.id;ctx.save();ctx.toast(`Imported ${f.name} ✓`);renderNotes(view,ctx);}catch(err){ctx.toast(err.message||'Could not read that file',5000);}e.target.value='';};
  $('#noteUrlAdd',view).onclick=async()=>{const url=$('#noteUrl',view).value.trim();if(!/^https?:\/\//i.test(url))return ctx.toast('Enter a valid http(s) URL');try{let text='';if(window.quizinoxNet?.fetchText){const r=await window.quizinoxNet.fetchText(url);if(!r.ok)throw Error(r.error||'URL fetch failed');text=r.text.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,150000);}else{const r=await fetch(url);if(!r.ok)throw Error(`HTTP ${r.status}`);text=(await r.text()).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,150000);}if(!text.trim())throw Error('No readable text found');const n={id:uid(),type:'note',title:new URL(url).hostname+' · imported',body:text,tags:['Web import'],parentId:notesFolder,sourceName:url,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};db.notes.unshift(n);activeNote=n.id;ctx.save();renderNotes(view,ctx);ctx.toast('Web page imported ✓');}catch(err){ctx.toast(`Could not import URL: ${err.message}. Some websites block browser reading; paste the text instead.`,6000);}};
  $('#noteSearchBtn',view).onclick=async()=>{const q=$('#noteSearch',view).value.trim();if(!q)return;const hits=notes.filter(n=>(n.title+' '+n.body+' '+(n.tags||[]).join(' ')).toLowerCase().includes(q.toLowerCase())).slice(0,12);const out=$('#noteSearchResult',view);out.innerHTML=hits.length?hits.map(n=>`<button class="l-hit" data-hit="${n.id}"><b>${esc(n.title)}</b><small>${esc((n.body||'').slice(0,180))}</small></button>`).join(''):'<small>No local matches. Ask AI to explore your saved material below.</small>';$$('[data-hit]',out).forEach(b=>b.onclick=()=>{activeNote=b.dataset.hit;notesFolder=notes.find(n=>n.id===activeNote)?.parentId||null;renderNotes(view,ctx);});const relevant=notes.map(n=>`## ${n.title}\n${(n.body||'').slice(0,5000)}`).join('\n\n').slice(0,25000);out.insertAdjacentHTML('beforeend',`<div class="l-ai-search"><textarea id="noteAiQuery" rows="2">${esc(q)}</textarea><button class="secondary" id="noteAskAi">✦ Ask AI across my notes</button><div id="noteAiAnswer"></div></div>`);$('#noteAskAi',out).onclick=async()=>{const answer=$('#noteAiAnswer',out);answer.textContent='Searching and connecting your saved notes…';try{const r=await ctx.AI.aiCall(`Answer the learner's question using the saved notes below. Prioritize the supplied material, cite note titles inline, distinguish what is present from what is not present, and do not invent quotations.\nQUESTION: ${$('#noteAiQuery',out).value}\nSAVED NOTES:\n${relevant}`,{json:false,maxTokens:1800});answer.innerHTML=esc(r.text).replace(/\n/g,'<br>');}catch(e){answer.textContent=e.message;}};};
}

/* ------------------------------ KNOWLEDGE VAULT ------------------------------ */
function renderVault(view,ctx){
  const db=ctx.db;arrays(db);const q=(view.dataset.vaultQuery||'').toLowerCase();const items=db.vault.filter(x=>!q||(x.title+' '+x.content+' '+(x.tags||[]).join(' ')).toLowerCase().includes(q));
  shell(view,'YOUR SECOND BRAIN','Personal Knowledge Vault','A searchable private library for important facts, explanations, concepts, difficult questions, screenshots and reference PDFs.',`<button class="primary" id="vaultAdd">＋ Add knowledge</button>`);
  view.innerHTML+=`<div class="l-vault-toolbar"><input id="vaultSearch" value="${esc(view.dataset.vaultQuery||'')}" placeholder="Search facts, tags, concepts or source…"/><button class="secondary" id="vaultSearchBtn">⌕ Search</button><button class="secondary" id="vaultAskAi">✦ Ask your Vault</button><button class="secondary" id="vaultImport">⇧ Add file / screenshot</button><input type="file" id="vaultFile" accept=".pdf,.txt,.md,.png,.jpg,.jpeg,.webp,image/*,application/pdf,text/plain" hidden/></div><section class="l-study-canvas-grid"><div class="panel l-study-board"><div class="panel-head"><div><span class="tag">VISUAL NOTEBOOK</span><h3>Study Canvas</h3><p>Write or draw with mouse, touch or stylus. Save snapshots into your Knowledge Vault.</p></div></div><div class="l-canvas-toolbar"><div class="l-canvas-tools"><button class="active" data-canvas-tool="pen" title="Pen">✎ Pen</button><button data-canvas-tool="highlighter" title="Highlighter">▰ Highlight</button><button data-canvas-tool="eraser" title="Eraser">▱ Eraser</button></div><div class="l-canvas-colours">${['#ffffff','#63d9ff','#78e08f','#ffe082','#ff8a80','#c79aff'].map((c,i)=>`<button data-canvas-color="${c}" class="${i===0?'active':''}" style="--swatch:${c}" title="Ink colour"></button>`).join('')}</div><label class="l-canvas-size">Size <input id="canvasBrushSize" type="range" min="1" max="14" value="4"/></label><div class="l-canvas-history"><button class="textbtn" id="canvasUndo" title="Undo">↶</button><button class="textbtn" id="canvasRedo" title="Redo">↷</button><button class="textbtn danger-text" id="canvasClear" title="Clear canvas">Clear</button></div></div><div class="l-canvas-wrap"><canvas id="vaultCanvas" width="1200" height="760" aria-label="Personal study drawing canvas"></canvas></div><label class="l-canvas-context">Typed notes / AI context<textarea id="canvasContext" rows="3" placeholder="Add typed points, a chapter excerpt or context that the AI assistant can read…"></textarea></label><div class="l-actions"><label class="l-canvas-title">Snapshot title <input id="canvasTitle" value="My study canvas"/></label><button class="primary" id="canvasSave">Save to Knowledge Vault</button><button class="secondary" id="canvasExport">⇩ Export PNG</button></div></div><aside class="panel l-study-ai"><div class="panel-head"><div><span class="tag">AI STUDY ASSISTANT</span><h3>Ask about your knowledge</h3><p>Ask questions across saved text notes and the typed context beside your drawing.</p></div></div><div id="vaultCanvasChat" class="l-canvas-chat"><div class="empty-mini"><b>Your study assistant is ready</b><small>Ask for a summary, concept connection, quiz or explanation based on your saved material.</small></div></div><label>Question<input id="vaultCanvasQuestion" placeholder="e.g. Explain these points with examples…"/></label><button class="primary full" id="vaultCanvasAsk">✦ Ask AI</button><small class="l-canvas-limit">Handwriting and screenshot pixels are saved visually but are not OCR-read in this release. Add typed context for AI analysis.</small></aside></section><div id="vaultAiResult" class="l-vault-ai-result"></div><div class="l-vault-grid">${items.length?items.map(x=>`<article class="panel l-vault-card" data-vault-card="${x.id}"><div class="l-vault-card-top"><span class="tag">${esc((x.kind||'note').toUpperCase())}</span><button class="textbtn danger-text" data-vault-del="${x.id}">×</button></div>${x.dataUrl&&x.mime?.startsWith('image/')?`<img class="l-vault-image" src="${x.dataUrl}" alt="${esc(x.title)}"/>`:x.kind==='pdf'?'<div class="l-pdf-preview">📄 PDF reference</div>':''}<h3>${esc(x.title)}</h3><p>${esc((x.content||'').slice(0,260))}${(x.content||'').length>260?'…':''}</p><div class="l-tags">${(x.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div><small>${esc(x.source||'Added to your library')} · ${fmtDate((x.createdAt||'').slice(0,10))}</small><div class="l-card-actions"><button class="textbtn" data-vault-open="${x.id}">Open ↗</button><button class="textbtn" data-vault-copy="${x.id}">Copy text</button></div></article>`).join(''):'<div class="panel empty-mini"><b>Your Knowledge Vault is ready</b><small>Save a useful explanation, screenshot, PDF extract, difficult concept or a note from a quiz result.</small></div>'}</div><div id="vaultEditor"></div>`;
  $('#vaultAdd',view).onclick=()=>vaultEditor(view,ctx,null);
  $('#vaultImport',view).onclick=()=>$('#vaultFile',view).click();
  $('#vaultFile',view).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const isImg=f.type.startsWith('image/'),isPdf=f.type==='application/pdf'||/\.pdf$/i.test(f.name);let content='',dataUrl='';if(isImg){if(f.size>8*1024*1024)throw Error('Please keep screenshots under 8 MB.');dataUrl=await fileRead(f);}else if(isPdf){if(f.size>8*1024*1024)throw Error('Please keep reference PDFs under 8 MB.');content=await ctx.pdfText(f);dataUrl=await fileRead(f);}else content=await f.text();addTo(db,'vault',{id:uid(),title:f.name,kind:isImg?'screenshot':isPdf?'pdf':'document',content,dataUrl,mime:f.type,tags:[isImg?'Screenshot':isPdf?'PDF':'Imported'],source:f.name,createdAt:new Date().toISOString()},ctx);ctx.toast('Added to Knowledge Vault ✓');renderVault(view,ctx);}catch(err){ctx.toast(err.message||'Could not import file',5000);}e.target.value='';};
  $('#vaultSearchBtn',view).onclick=()=>{view.dataset.vaultQuery=$('#vaultSearch',view).value;renderVault(view,ctx);};
  $('#vaultAskAi',view).onclick=async()=>{const query=$('#vaultSearch',view).value.trim();if(!query)return ctx.toast('Type a question or concept in the search box first');const records=db.vault.map(x=>`SOURCE: ${x.title} [${x.kind||'note'}]\nTAGS: ${(x.tags||[]).join(', ')}\nCONTENT: ${(x.content||'').slice(0,2600)}`).join('\n\n').slice(0,24000);const out=$('#vaultAiResult',view);out.innerHTML='<div class="l-ai-loading">✦ Connecting your saved knowledge…</div>';try{const r=await ctx.AI.aiCall(`Answer the learner's question using only the saved Knowledge Vault records below. Cite the relevant saved item titles in the answer. Distinguish information present in saved records from information missing. Some screenshot/PDF records may have no extracted text; never pretend to have read their pixels.\nQUESTION: ${query}\nSAVED KNOWLEDGE:\n${records}`,{json:false,maxTokens:1800,temperature:.3});out.innerHTML=`<div class="l-ai-search"><b>✦ Answer from your Knowledge Vault</b><div>${esc(r.text).replace(/\n/g,'<br>')}</div></div>`;}catch(e){out.textContent=e.message;}};
  $$('[data-vault-open]',view).forEach(b=>b.onclick=()=>vaultEditor(view,ctx,db.vault.find(x=>x.id===b.dataset.vaultOpen)));
  $$('[data-vault-del]',view).forEach(b=>b.onclick=async()=>{if(!await ctx.confirmBox('Remove saved item?','This item will be deleted from your local Knowledge Vault.','Delete',true))return;db.vault=db.vault.filter(x=>x.id!==b.dataset.vaultDel);ctx.save();renderVault(view,ctx);});
  $$('[data-vault-copy]',view).forEach(b=>b.onclick=()=>{const x=db.vault.find(x=>x.id===b.dataset.vaultCopy);navigator.clipboard?.writeText(x?.content||'');ctx.toast('Text copied');});
  initVaultCanvas(view,ctx);
  $('#vaultCanvasAsk',view).onclick=async()=>{const query=$('#vaultCanvasQuestion',view).value.trim();if(!query)return ctx.toast('Write a question for your AI assistant');const out=$('#vaultCanvasChat',view),typed=$('#canvasContext',view).value.trim();const saved=db.vault.filter(x=>x.content).map(x=>`SOURCE: ${x.title}\n${(x.content||'').slice(0,1800)}`).join('\n\n').slice(0,18000);out.insertAdjacentHTML('beforeend',`<div class="l-canvas-chat-msg user"><b>You</b><p>${esc(query)}</p></div><div class="l-ai-loading">✦ Analysing your saved study material…</div>`);const loading=out.lastElementChild;try{const r=await ctx.AI.aiCall(`You are the QUIZINOX Personal Study Assistant. Answer using the typed canvas context and saved Knowledge Vault text. Do not claim to read the visible drawing, handwritten pixels or screenshots. Clearly distinguish supported content from explanation or inference. Be useful for exam preparation, and cite source item titles inline.\nQUESTION: ${query}\nTYPED CANVAS CONTEXT: ${typed||'No typed canvas context supplied.'}\nSAVED VAULT MATERIAL: ${saved||'No saved text yet.'}`,{json:false,maxTokens:1800,temperature:.35});loading.outerHTML=`<div class="l-canvas-chat-msg ai"><b>QUIZINOX AI</b><p>${esc(r.text).replace(/\n/g,'<br>')}</p></div>`;}catch(e){loading.outerHTML=`<div class="l-canvas-chat-msg ai error"><b>AI error</b><p>${esc(e.message)}</p></div>`;}out.scrollTop=out.scrollHeight;};
}
function initVaultCanvas(view,ctx){
  const canvas=$('#vaultCanvas',view);if(!canvas)return;const c=canvas.getContext('2d');let tool='pen',colour='#ffffff',drawing=false,last=null,history=[],redo=[];
  const drawGrid=()=>{c.save();c.globalCompositeOperation='source-over';c.globalAlpha=1;c.fillStyle='#202731';c.fillRect(0,0,canvas.width,canvas.height);c.strokeStyle='rgba(190,210,235,.09)';c.lineWidth=1;for(let x=0;x<canvas.width;x+=32){c.beginPath();c.moveTo(x,0);c.lineTo(x,canvas.height);c.stroke();}for(let y=0;y<canvas.height;y+=32){c.beginPath();c.moveTo(0,y);c.lineTo(canvas.width,y);c.stroke();}c.restore();};
  const snapshot=()=>{history.push(canvas.toDataURL('image/png'));if(history.length>16)history.shift();redo=[];};
  const restore=url=>{const im=new Image();im.onload=()=>{c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(im,0,0,canvas.width,canvas.height);};im.src=url;};
  drawGrid();snapshot();
  const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
  canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;last=point(e);canvas.setPointerCapture?.(e.pointerId);c.beginPath();c.moveTo(last.x,last.y);});
  canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e),size=Number($('#canvasBrushSize',view).value)||4,scale=canvas.width/canvas.getBoundingClientRect().width;c.save();c.lineCap='round';c.lineJoin='round';c.lineWidth=size*scale*(e.pointerType==='pen'?Math.max(.35,e.pressure||.5):1);if(tool==='eraser'){c.globalCompositeOperation='destination-out';c.globalAlpha=1;}else{c.globalCompositeOperation='source-over';c.strokeStyle=colour;c.globalAlpha=tool==='highlighter'?.28:1;}c.beginPath();c.moveTo(last.x,last.y);c.lineTo(p.x,p.y);c.stroke();c.restore();last=p;});
  const finish=()=>{if(!drawing)return;drawing=false;last=null;snapshot();};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('lostpointercapture',finish);
  $$('[data-canvas-tool]',view).forEach(b=>b.onclick=()=>{tool=b.dataset.canvasTool;$$('[data-canvas-tool]',view).forEach(x=>x.classList.toggle('active',x===b));});
  $$('[data-canvas-color]',view).forEach(b=>b.onclick=()=>{colour=b.dataset.canvasColor;$$('[data-canvas-color]',view).forEach(x=>x.classList.toggle('active',x===b));if(tool==='eraser'){tool='pen';$$('[data-canvas-tool]',view).forEach(x=>x.classList.toggle('active',x.dataset.canvasTool==='pen'));}});
  $('#canvasUndo',view).onclick=()=>{if(history.length<2)return;redo.push(history.pop());restore(history[history.length-1]);};
  $('#canvasRedo',view).onclick=()=>{if(!redo.length)return;const next=redo.pop();history.push(next);restore(next);};
  $('#canvasClear',view).onclick=()=>{drawGrid();snapshot();};
  const blob=()=>new Promise(resolve=>canvas.toBlob(resolve,'image/png'));
  $('#canvasExport',view).onclick=async()=>{const b=await blob();if(!b)return ctx.toast('Could not export canvas');await ctx.saveFile(`QUIZINOX-Study-Canvas-${Date.now()}.png`,b,'image/png');};
  $('#canvasSave',view).onclick=async()=>{const dataUrl=canvas.toDataURL('image/png');if(dataUrl.length>11*1024*1024)return ctx.toast('This canvas is too large to save. Export it as PNG instead.',5000);addTo(ctx.db,'vault',{id:uid(),title:$('#canvasTitle',view).value.trim()||'Study canvas',kind:'study-canvas',content:$('#canvasContext',view).value.trim(),dataUrl,mime:'image/png',tags:['Study canvas','Handwritten notes'],source:'Visual study canvas',createdAt:new Date().toISOString()},ctx);ctx.toast('Canvas snapshot saved in your Knowledge Vault ✓');renderVault(view,ctx);};
}
function vaultEditor(view,ctx,item){const edit=!!item;$('#vaultEditor',view).innerHTML=`<div class="mode-overlay l-vault-overlay"><div class="mode-dialog wide"><button class="mode-close" id="vaultClose">×</button><div class="eyebrow">PERSONAL KNOWLEDGE VAULT</div><h2>${edit?'Edit saved knowledge':'Save new knowledge'}</h2><label>Title<input id="vaultTitle" value="${esc(item?.title||'')}" placeholder="e.g. Basic Structure Doctrine"/></label><label>Content / explanation<textarea id="vaultContent" rows="9" placeholder="Paste an explanation, important facts, a concept or a difficult question…">${esc(item?.content||'')}</textarea></label><label>Tags<input id="vaultTags" value="${esc((item?.tags||[]).join(', '))}" placeholder="Polity, Supreme Court, Important…"/></label>${item?.dataUrl&&item.mime?.startsWith('image/')?`<img class="l-vault-preview" src="${item.dataUrl}" alt="Saved reference"/>`:item?.kind==='pdf'?`<a class="secondary" href="${item.dataUrl}" download="${esc(item.title)}">Open / download original PDF</a>`:''}<div class="dialog-actions"><button class="secondary" id="vaultClose2">Cancel</button><button class="primary" id="vaultSave">Save to Vault</button></div></div></div>`;const close=()=>$('.l-vault-overlay',view)?.remove();$('#vaultClose',view).onclick=close;$('#vaultClose2',view).onclick=close;$('#vaultSave',view).onclick=()=>{const title=$('#vaultTitle',view).value.trim()||'Untitled knowledge';const content=$('#vaultContent',view).value;const tags=$('#vaultTags',view).value.split(',').map(x=>x.trim()).filter(Boolean);if(edit)Object.assign(item,{title,content,tags,updatedAt:new Date().toISOString()});else addTo(ctx.db,'vault',{id:uid(),title,content,tags,kind:'note',createdAt:new Date().toISOString()},ctx);if(edit)ctx.save();close();renderVault(view,ctx);ctx.toast('Saved in your Knowledge Vault ✓');};}

/* -------------------------------- ROADMAPS -------------------------------- */
function createRoadmap(name,date,syllabus){const topics=syllabus.split(/\n|;|•/).map(x=>x.replace(/^[-*\d.)\s]+/,'').trim()).filter(Boolean);const base=topics.length?topics:['Complete syllabus mapping','Core concepts and static syllabus','Daily question practice','Previous year questions','Full-length mock tests','Revision and weak-area correction'];const d=Math.max(1,dayDiff(date));const entries=[];const add=(title,category,ratio)=>entries.push({id:uid(),title,category,dueDate:dateKey(new Date(Date.now()+Math.max(0,Math.min(d-1,Math.round((d-1)*ratio)))*86400000)),done:false});
  base.forEach((t,i)=>{const r=base.length===1?0.35:i/(base.length+1);add(`Study: ${t}`,'Study',r*0.75);add(`Revise + practise: ${t}`,'Revision',Math.min(.92,r*0.75+.18));});
  add('Complete one full-length mock test','Mock',.72);add('Analyse mistakes and revise weak areas','Analysis',.84);add('Final rapid revision + exam strategy','Final revision',.96);
  return{id:uid(),name,date,syllabus,createdAt:new Date().toISOString(),tasks:entries};}
function rescheduleRoadmap(r){const pending=r.tasks.filter(t=>!t.done);if(!pending.length)return;const remain=Math.max(0,dayDiff(r.date));pending.sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)));pending.forEach((t,i)=>{const offset=remain===0?0:Math.round((remain-1)*((i+1)/(pending.length+1)));t.dueDate=dateKey(new Date(Date.now()+offset*86400000));});r.updatedAt=new Date().toISOString();}
function renderRoadmaps(view,ctx){const db=ctx.db;arrays(db);shell(view,'MULTI-EXAM PLANNER','Exam Countdown Roadmap','Create unlimited exam timelines and dated milestones. The pending plan automatically redistributes when you complete tasks.',`<button class="primary" id="roadmapAdd">＋ Add exam / date</button>`);view.innerHTML+=`<div class="l-roadmap-grid">${db.roadmaps.length?db.roadmaps.map(r=>{r.tasks=Array.isArray(r.tasks)?r.tasks:[];const done=r.tasks.filter(t=>t.done).length,pct=r.tasks.length?Math.round(done/r.tasks.length*100):0,days=dayDiff(r.date);return`<section class="panel l-roadmap-card"><div class="l-roadmap-title"><div><span class="tag">${days<0?'DATE PASSED':days===0?'TODAY':`${days} DAYS LEFT`}</span><h2>${esc(r.name)}</h2><small>Target date · ${fmtDate(r.date)}</small></div><button class="textbtn danger-text" data-rm-del="${r.id}">Delete</button></div><div class="l-progress"><i style="width:${pct}%"></i></div><div class="l-roadmap-stats"><b>${pct}% complete</b><span>${done}/${r.tasks.length} tasks completed</span></div><div class="l-roadmap-timeline">${r.tasks.slice().sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))).map(t=>`<label class="l-roadmap-task ${t.done?'done':''}"><input type="checkbox" data-task="${r.id}|${t.id}" ${t.done?'checked':''}/><span class="l-stage-dot"></span><span><b>${esc(t.title)}</b><small>${esc(t.category)} · ${fmtDate(t.dueDate)} ${!t.done&&t.dueDate<today()&&days>0?'<em>Rescheduling</em>':''}</small></span></label>`).join('')}</div><div class="l-roadmap-addtask"><input data-newtask="${r.id}" placeholder="Add a custom task…"/><button class="secondary" data-addtask="${r.id}">＋ Add task</button></div></section>`;}).join(''):'<div class="panel empty-mini"><b>No countdowns yet</b><small>Add UPSC Prelims, Mains, an interview, a recruitment exam, a course deadline or any other important date. There is no fixed limit.</small></div>'}</div>`;
  $('#roadmapAdd',view).onclick=()=>{const {el,close}=ctx.modal(`<div class="eyebrow">NEW COUNTDOWN</div><h2>Create an exam roadmap</h2><label>Exam / milestone name<input id="rmName" placeholder="e.g. UPSC CSE Prelims 2027"/></label><label>Target date<input id="rmDate" type="date" min="${today()}"/></label><label>Syllabus / topics (one per line)<textarea id="rmSyllabus" rows="7" placeholder="Polity — Parliament\nModern History — 1857 onwards\nEconomy — Inflation\nDaily PYQ practice\nMock tests"></textarea></label><p class="muted">The roadmap will split topics into study and revision tasks, then add mock analysis and final revision milestones.</p><div class="dialog-actions"><button class="secondary" data-cancel>Cancel</button><button class="primary" data-create>Create roadmap</button></div>`,{wide:true});$('[data-cancel]',el).onclick=close;$('[data-create]',el).onclick=()=>{const name=$('#rmName',el).value.trim(),date=$('#rmDate',el).value,syllabus=$('#rmSyllabus',el).value;if(!name||!date)return ctx.toast('Enter a name and target date');addTo(ctx.db,'roadmaps',createRoadmap(name,date,syllabus),ctx);close();renderRoadmaps(view,ctx);};};
  $$('[data-task]',view).forEach(c=>c.onchange=()=>{const[id,tid]=c.dataset.task.split('|'),r=db.roadmaps.find(x=>x.id===id),t=r?.tasks.find(x=>x.id===tid);if(!t)return;t.done=c.checked;if(c.checked)rescheduleRoadmap(r);ctx.save();renderRoadmaps(view,ctx);});
  $$('[data-addtask]',view).forEach(b=>b.onclick=()=>{const r=db.roadmaps.find(x=>x.id===b.dataset.addtask),inp=$(`[data-newtask="${r.id}"]`,view),title=inp.value.trim();if(!title)return;r.tasks.push({id:uid(),title,category:'Custom',dueDate:today(),done:false});rescheduleRoadmap(r);ctx.save();renderRoadmaps(view,ctx);});
  $$('[data-rm-del]',view).forEach(b=>b.onclick=async()=>{if(!await ctx.confirmBox('Delete this roadmap?','Its tasks and progress will be removed.','Delete',true))return;db.roadmaps=db.roadmaps.filter(r=>r.id!==b.dataset.rmDel);ctx.save();renderRoadmaps(view,ctx);});
}

/* -------------------------------- TEACHER -------------------------------- */
function learnerContext(db,topic){
  const terms=[...new Set(String(topic||'').toLowerCase().match(/[\p{L}\p{N}]{3,}/gu)||[])].filter(w=>!['the','and','for','from','with','what','how','why','basic','advanced','topic','teach','about'].includes(w));
  const matches=value=>{const t=String(value||'').toLowerCase();return terms.length?terms.some(w=>t.includes(w)):false;};
  const misses=db.attempts.flatMap(a=>(a.details||[]).map(d=>({...d,quizTitle:a.quizTitle,subject:d.subject||a.subject}))).filter(d=>d.status==='wrong').slice(0,60);
  const related=misses.filter(d=>matches([d.question,d.topic,d.subject,d.quizTitle].join(' '))).slice(0,10);
  const revision=Object.values(db.revision||{}).filter(x=>matches([x.text,x.question,x.topic].join(' '))).slice(0,10);
  const notes=db.notes.filter(n=>n.type==='note'&&matches(n.title+' '+n.body)).slice(0,6);
  const vault=db.vault.filter(v=>matches(v.title+' '+v.content)).slice(0,6);
  const recentSummary=db.attempts.slice(0,12).map(a=>`- ${a.quizTitle}: ${a.percent}% (${a.correct}/${a.total} correct), ${a.subject||'General'}, mode ${a.mode||'quiz'}`).join('\n');
  return`Topic keywords used for matching: ${terms.join(', ')||'none'}\nRecent overall learning record:\n${recentSummary||'No attempts recorded yet.'}\nTopic-related incorrect answers:\n${(related.length?related:misses.slice(0,8)).map(x=>`- ${x.question} | learner chose ${x.selected??'blank'}; correct index ${x.correct}; topic ${x.topic||'not tagged'}; explanation ${x.explanation||''}`).join('\n')||'No recorded mistakes yet.'}\nTopic-related revision history:\n${revision.map(x=>`- ${x.text||x.question||x.topic||'Scheduled review'} · state ${x.state||'pending'} · due ${x.due||x.nextReview||'unknown'}`).join('\n')||'No topic-specific scheduled revision found.'}\nSaved notes:\n${notes.map(n=>`- ${n.title}: ${(n.body||'').slice(0,1600)}`).join('\n')}\nVault:\n${vault.map(n=>`- ${n.title}: ${(n.content||'').slice(0,1000)}`).join('\n')}`;
}
function renderTeacher(view,ctx){const db=ctx.db;arrays(db);const current=db.teacherSessions[0];shell(view,'PERSONAL AI EDUCATOR','QUIZINOX TEACHER · Teach Me Mode','A teacher that uses your previous attempts, mistakes, notes and revision history to explain concepts at your level, then verifies understanding.',`<button class="secondary" id="teacherNew">＋ New lesson</button>`);view.innerHTML+=`<div class="l-teacher-layout"><div class="panel l-teacher-start"><div class="l-teacher-orb">✦</div><h2>What should we learn today?</h2><p>Start from zero or ask for an advanced explanation. The teacher will explain, give an example, ask 3–5 questions and reteach weak answers.</p><label>Topic / concept<input id="teachTopic" placeholder="e.g. Basic Structure Doctrine, Inflation, Federalism…"/></label><div class="form-grid"><label>Starting level<select id="teachLevel"><option>Beginner — teach from zero</option><option>Intermediate — I know the basics</option><option>Advanced — go deep</option><option>UPSC CSE — exam oriented</option></select></label><label>Teaching language<select id="teachLang"><option>Follow app setting</option><option>English</option><option>Hindi</option><option>Hinglish</option></select></label></div><button class="primary full" id="teachStart">✦ Teach me this topic</button><small class="muted">Personal context: ${db.attempts.length} attempts · ${db.notebook?.items?Object.keys(db.notebook.items).length:0} mistake notes · ${db.notes.filter(n=>n.type==='note').length} personal notes · ${db.revision?Object.keys(db.revision).length:0} revision items</small></div><div class="panel l-teacher-session" id="teacherSession">${current?.lesson?teacherLessonHtml(current):'<div class="empty-mini"><b>Your next lesson will appear here</b><small>Each lesson includes an explanation, a worked example, active recall questions and adaptive reteaching.</small></div>'}</div></div>${db.teacherSessions.length>1?`<section class="panel l-teacher-history"><div class="panel-head"><div><h3>Previous lessons</h3><p>Continue a saved topic or revisit the questions you answered.</p></div></div><div>${db.teacherSessions.slice(1).map(x=>`<button class="l-teacher-history-item" data-teacher-session="${x.id}"><b>${esc(x.topic||'New lesson')}</b><small>${esc(x.level||'Lesson')} · ${fmtDate((x.createdAt||'').slice(0,10))}</small></button>`).join('')}</div></section>`:''}`;
  $$('[data-teacher-session]',view).forEach(b=>b.onclick=()=>{const i=db.teacherSessions.findIndex(x=>x.id===b.dataset.teacherSession);if(i>0){const [chosen]=db.teacherSessions.splice(i,1);db.teacherSessions.unshift(chosen);ctx.save();renderTeacher(view,ctx);}});
  $('#teacherNew',view).onclick=()=>{$('#teachTopic',view).value='';$('#teacherSession',view).innerHTML='<div class="empty-mini"><b>Ready for a new lesson</b><small>Enter a topic and start a fresh personalised lesson.</small></div>';$('#teachTopic',view).focus();};
  $('#teachStart',view).onclick=async()=>{const topic=$('#teachTopic',view).value.trim();if(!topic)return ctx.toast('Enter a topic first');const level=$('#teachLevel',view).value,lang=$('#teachLang',view).value==='Follow app setting'?db.settings.tutorLang:$('#teachLang',view).value;const s={id:uid(),topic,level,lang,createdAt:new Date().toISOString(),messages:[],lesson:null};db.teacherSessions.unshift(s);ctx.save();const area=$('#teacherSession',view);area.innerHTML='<div class="l-ai-loading">✦ Building your personalised lesson…</div>';try{const prompt=`You are QUIZINOX TEACHER, an exceptionally clear, adaptive exam tutor. Teach the topic: ${topic}. Learner level: ${level}. Reply language: ${lang}. Use this verified learner history context to target weak concepts:\n${learnerContext(db,topic)}\nReturn valid JSON only with: {"explanation":"structured but understandable teaching from the correct starting level","example":"one worked real-world or exam-oriented example","keyPoints":["..."],"questions":[{"question":"...","options":["A...","B...","C...","D..."],"correct":0,"explanation":"why this is correct and why distractors fail"}]}. Create 4 questions, progressively harder, ensure exactly 4 options and correct index 0-3. Do not invent citations or learner history.`;const r=await ctx.AI.aiCall(prompt,{json:true,maxTokens:4200,temperature:.35});let data=ctx.AI.parseJsonLoose(r.text);if(!data||!Array.isArray(data.questions))throw Error('The AI response could not be parsed. Try again.');data.questions=data.questions.slice(0,5);s.lesson=data;s.messages.push({role:'teacher',text:data.explanation});ctx.save();renderTeacher(view,ctx);}catch(e){area.innerHTML=`<div class="notice">${esc(e.message)}</div>`;}}
  const s=current;if(s?.lesson)wireTeacherLesson(view,ctx,s);
}
function teacherLessonHtml(s){const l=s.lesson||{};return`<div class="l-lesson-head"><span class="tag">${esc(s.level||'PERSONALISED LESSON')}</span><small>${fmtDate((s.createdAt||'').slice(0,10))}</small></div><h2>${esc(s.topic)}</h2><div class="l-lesson-body">${esc(l.explanation||'').replace(/\n/g,'<br>')}</div><div class="l-example"><b>🧩 Worked example</b><p>${esc(l.example||'')}</p></div>${l.keyPoints?.length?`<div class="l-keypoints"><b>Remember these</b>${l.keyPoints.map(x=>`<p>✓ ${esc(x)}</p>`).join('')}</div>`:''}<div class="l-check-questions"><h3>Check your understanding</h3><p class="muted">Answer each question. Incorrect answers trigger a targeted reteaching note.</p>${(l.questions||[]).map((q,i)=>`<div class="l-teach-q" data-tq="${i}"><b>${i+1}. ${esc(q.question)}</b><div>${(q.options||[]).map((o,j)=>`<button class="l-teach-option" data-ta="${i}|${j}">${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}</div><p class="l-teach-feedback" id="tfeed${i}"></p></div>`).join('')}</div><div class="l-followup"><input id="teachFollowup" placeholder="Ask a follow-up or say what is confusing…"/><button class="secondary" id="teachAsk">Ask teacher</button></div><div id="teachReply"></div>`;}
function wireTeacherLesson(view,ctx,s){$$('[data-ta]',view).forEach(b=>b.onclick=async()=>{const[i,j]=b.dataset.ta.split('|').map(Number),q=s.lesson.questions[i],feed=$(`#tfeed${i}`,view);$$(`[data-tq="${i}"] .l-teach-option`,view).forEach(x=>x.disabled=true);const good=j===Number(q.correct);b.classList.add(good?'correct':'incorrect');if(!good)$$(`[data-ta="${i}|${q.correct}"]`,view).forEach(x=>x.classList.add('correct'));feed.innerHTML=`<b>${good?'✓ Correct — good understanding':'↻ Let us repair this concept'}</b><br>${esc(q.explanation||'')}`;if(!good){feed.insertAdjacentHTML('beforeend','<br><em>Teacher is reteaching this concept in simpler language…</em>');try{const r=await ctx.AI.aiCall(`You are QUIZINOX teacher. Learner answered this question incorrectly while learning ${s.topic}. Question: ${q.question}. Learner selected: ${q.options?.[j]||j}. Correct answer: ${q.options?.[q.correct]||q.correct}. Explanation: ${q.explanation||''}. Reteach only the underlying concept in ${s.lang||ctx.db.settings.tutorLang}, using simpler language, one analogy and one new short example. Then give one one-line memory cue. Do not give another MCQ yet.`,{json:false,maxTokens:900,temperature:.35});feed.innerHTML+=`<div class="l-reteach"><b>🎓 Personal reteaching</b><p>${esc(r.text).replace(/\n/g,'<br>')}</p></div>`;s.messages.push({role:'teacher',text:r.text,kind:'reteach'});}catch(e){feed.insertAdjacentHTML('beforeend',`<br><small>Could not load a new explanation: ${esc(e.message)}</small>`);}}s.lesson.answers||={};s.lesson.answers[i]={chosen:j,correct:good};ctx.save();});$('#teachAsk',view)?.addEventListener('click',async()=>{const q=$('#teachFollowup',view).value.trim();if(!q)return;const out=$('#teachReply',view);out.textContent='Teacher is thinking…';try{const r=await ctx.AI.aiCall(`Continue teaching ${s.topic}. Original lesson: ${s.lesson.explanation}. Learner asks: ${q}. Reply in ${s.lang||ctx.db.settings.tutorLang}, concise but thorough. If there is a misconception, explain it with an example.`,{json:false,maxTokens:1400});out.innerHTML=esc(r.text).replace(/\n/g,'<br>');s.messages.push({role:'learner',text:q},{role:'teacher',text:r.text});ctx.save();}catch(e){out.textContent=e.message;}});}

/* -------------------------------- DISCUSSION -------------------------------- */
const MODES=['Debate with AI','Group Discussion Simulation','UPSC Interview Discussion','Pros & Cons Analysis','Ethical Dilemma Discussion','Mains Answer Discussion'];
function renderDiscussion(view,ctx){const db=ctx.db;arrays(db);const d=db.discussions[0];shell(view,'ARGUE · LISTEN · IMPROVE','QUIZINOX DISCUSSION ROOM','Develop conceptual clarity and analytical thinking through structured AI debate, group discussions, interview practice and ethical dilemmas.',`<button class="secondary" id="debateNew">＋ New discussion</button>`);view.innerHTML+=`<div class="l-discussion-layout"><div class="panel l-discussion-config"><span class="tag">LIVE LEARNING SIMULATION</span><h2>Take a position. Defend it.</h2><label>Discussion mode<select id="debateMode">${MODES.map(m=>`<option>${m}</option>`).join('')}</select></label><label>Topic<input id="debateTopic" placeholder="e.g. Should India adopt simultaneous elections?"/></label><label>Your position<select id="debateSide"><option value="Pro">I support / agree (Pro)</option><option value="Con">I oppose / disagree (Con)</option><option value="Neutral">I will analyse both sides</option></select></label><button class="primary full" id="debateStart">Start discussion ↗</button><div class="l-voice-tip">🎙️ Use the microphone next to the argument box to dictate. On unsupported devices, use Android keyboard voice input or Windows voice typing (Win + H).</div></div><div class="panel l-debate-room" id="debateRoom">${d?discussionHtml(d):'<div class="empty-mini"><b>Your discussion room is waiting</b><small>Start a topic to receive the AI opening position, submit arguments and get rebuttals and a final AI judge report.</small></div>'}</div></div>${db.discussions.length>1?`<section class="panel l-discussion-history"><div class="panel-head"><div><h3>Previous discussions</h3><p>Reopen a saved debate, interview or answer review.</p></div></div><div>${db.discussions.slice(1).map(x=>`<button class="l-discussion-history-item" data-discussion="${x.id}"><b>${esc(x.topic||'Untitled discussion')}</b><small>${esc(x.mode||'Discussion')} · ${fmtDate((x.createdAt||'').slice(0,10))} · ${x.status==='complete'?'Judged':'In progress'}</small></button>`).join('')}</div></section>`:''}`;
  $$('[data-discussion]',view).forEach(b=>b.onclick=()=>{const i=db.discussions.findIndex(x=>x.id===b.dataset.discussion);if(i>0){const [chosen]=db.discussions.splice(i,1);db.discussions.unshift(chosen);ctx.save();renderDiscussion(view,ctx);}});
  $('#debateNew',view).onclick=()=>{$('#debateTopic',view).value='';$('#debateRoom',view).innerHTML='<div class="empty-mini"><b>Ready for a new discussion</b><small>Choose a mode, enter a topic and start the session. Your previous sessions remain saved below.</small></div>';$('#debateTopic',view).focus();};
  $('#debateStart',view).onclick=async()=>{const topic=$('#debateTopic',view).value.trim();if(!topic)return ctx.toast('Enter a topic first');const mode=$('#debateMode',view).value,side=$('#debateSide',view).value;const x={id:uid(),mode,topic,userSide:side,aiSide:side==='Pro'?'Con':side==='Con'?'Pro':'Both sides',round:0,status:'active',messages:[],createdAt:new Date().toISOString()};db.discussions.unshift(x);ctx.save();await discussionAi(x,ctx,discussionStartPrompt(x));renderDiscussion(view,ctx);};
  if(d)wireDiscussion(view,ctx,d);
}
function discussionHtml(d){return`<div class="l-debate-head"><div><span class="tag">${esc(d.mode)}</span><h2>${esc(d.topic)}</h2><small>You: ${esc(d.userSide)} · AI: ${esc(d.aiSide)} · Round ${d.round||0}/5</small></div><span class="l-live-dot">${d.status==='active'?'● LIVE':d.status==='error'?'⚠ AI ERROR':'✓ COMPLETE'}</span></div><div class="l-debate-stream">${(d.messages||[]).map(m=>`<article class="l-debate-msg ${m.role}"><div><b>${m.role==='user'?'YOU':m.role==='judge'?'AI JUDGE':'AI OPPONENT'}</b><small>${m.round?`ROUND ${m.round}`:''}</small></div><p>${esc(m.text).replace(/\n/g,'<br>')}</p></article>`).join('')}</div>${d.status==='active'||d.status==='error'?`<div class="l-debate-compose"><textarea id="debateArgument" rows="3" maxlength="2000" placeholder="Present your argument, evidence, example or counterpoint…"></textarea><div class="l-debate-actions"><button class="secondary" id="debateVoice">🎙️ Speak</button><small id="voiceStatus">${(d.round||0)>=5?'Maximum rounds reached — ask for the judge report.':'Sent to your selected AI provider for this session.'}</small><button class="primary" id="debateSend" ${(d.round||0)>=5?'disabled':''}>Submit argument ↗</button></div>${(d.round||0)>=5?'<small class="muted">Five rounds completed — ask the AI Judge for your evaluation.</small>':''}<button class="textbtn" id="debateJudge">🏆 End and ask AI Judge to evaluate</button></div>`:`${d.judgement?`<div class="l-judge-result"><h3>🏆 AI Judge assessment</h3><div class="l-judge-scores">${Object.entries(d.judgement.scores||{}).map(([k,v])=>`<div><b>${esc(k)}</b><strong>${esc(v)}/10</strong></div>`).join('')}</div><h3>Overall result: ${esc(d.judgement.winner||'Assessment')}</h3><p>${esc(d.judgement.summary||'')}</p><p><b>How to improve:</b> ${esc(d.judgement.improvement||'')}</p>${d.judgement.factualCorrections?.length?`<div class="l-judge-corrections"><b>Factual checks</b>${d.judgement.factualCorrections.map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}</div>`:''}`}`;}
function discussionStartPrompt(d){const base=`Topic: ${d.topic}. Learner position: ${d.userSide}. Reply in a respectful, challenging, evidence-conscious way. Do not invent statistics, cases or citations.`;const prompts={
  'Debate with AI':`Open a structured debate. Take the ${d.aiSide} position. Give a concise thesis, two strong arguments, acknowledge one trade-off and ask one focused challenge question. ${base}`,
  'Group Discussion Simulation':`Act as a professional group-discussion moderator. Simulate three distinct participants (for example: public administrator, economist and social-policy researcher), each with a clearly labelled short opening viewpoint. Show respectful disagreement and different lenses, then invite the learner to enter the discussion with a focused prompt. ${base}`,
  'UPSC Interview Discussion':`Act as a UPSC board chair. Give a brief realistic opening and ask exactly one probing interview question at a time. Do not reveal a model answer before the learner responds. Assess constitutional values, balance, clarity and composure over the session. ${base}`,
  'Pros & Cons Analysis':`Present the strongest arguments both in favour and against the proposition, the stakeholders affected, implementation constraints and a balanced synthesis. End by asking the learner to weigh the trade-offs. ${base}`,
  'Ethical Dilemma Discussion':`Present a realistic public-service ethical dilemma connected to this topic. Identify stakeholders and competing values but do not dictate a solution. Ask the learner what they would do and why; then probe consequences, fairness, legality and accountability. ${base}`,
  'Mains Answer Discussion':`Act as a UPSC Mains mentor. Ask the learner to draft a structured answer to the topic (introduction, multidimensional body, examples and conclusion). Do not write the answer for them first. Explain the expected directive and dimensions, then invite their draft. ${base}`
};return prompts[d.mode]||prompts['Debate with AI'];}
function discussionReplyPrompt(d,text){const base=`Mode: ${d.mode}. Topic: ${d.topic}. Learner position: ${d.userSide}. Learner's latest contribution: ${text}. Round ${d.round} of 5. Stay accurate and fair; distinguish verified facts from analysis. Do not declare a winner yet.`;const prompts={
  'Debate with AI':`Respond as the ${d.aiSide} opponent. Identify the learner's strongest point, rebut it with sound reasoning, acknowledge any valid concession, and end with one focused counter-question. ${base}`,
  'Group Discussion Simulation':`Continue the group discussion as moderator. Give two or three short, clearly labelled participant reactions that build on or respectfully challenge the learner's contribution. Ensure different perspectives and avoid repeating the same view. End by inviting the learner to respond to the most important disagreement. ${base}`,
  'UPSC Interview Discussion':`Respond as a UPSC interview board. Briefly acknowledge the answer, identify one strength and one area to sharpen, then ask exactly one deeper follow-up question. Keep the tone probing but courteous; do not provide a long model answer. ${base}`,
  'Pros & Cons Analysis':`Assess the learner's point, add the strongest missing argument on the opposite side, identify a trade-off or stakeholder impact, and ask how the learner would balance both sides. ${base}`,
  'Ethical Dilemma Discussion':`Challenge the learner's decision through a stakeholder or constitutional-values lens. Explore consequences, fairness, legality, transparency and accountability. Ask one probing question without prescribing a single simplistic answer. ${base}`,
  'Mains Answer Discussion':`Evaluate the learner's answer like a UPSC Mains mentor. Comment on demand of question, introduction, structure, dimensions, examples, constitutional/current-affairs grounding, balance and conclusion. Give 2-3 actionable improvements and ask them to revise one specific weakness. ${base}`
};return prompts[d.mode]||prompts['Debate with AI'];}
async function discussionAi(d,ctx,prompt){const room=document.querySelector('#debateRoom');if(room)room.innerHTML='<div class="l-ai-loading">✦ AI is preparing its response…</div>';try{const r=await ctx.AI.aiCall(prompt,{json:false,maxTokens:1900,temperature:.4});d.messages.push({role:'ai',text:r.text,round:d.round||0});d.status='active';ctx.save();}catch(e){d.status='error';d.messages.push({role:'ai',text:`AI could not respond: ${e.message}`});ctx.save();}}
function wireDiscussion(view,ctx,d){$('#debateSend',view)?.addEventListener('click',async()=>{const text=$('#debateArgument',view).value.trim();if(!text)return;if((d.round||0)>=5)return ctx.toast('This discussion has reached five rounds. Ask the AI Judge to evaluate it.');d.round=(d.round||0)+1;d.messages.push({role:'user',text,round:d.round});ctx.save();renderDiscussion(view,ctx);await discussionAi(d,ctx,discussionReplyPrompt(d,text));renderDiscussion(view,ctx);});
  $('#debateJudge',view)?.addEventListener('click',async()=>{const transcript=d.messages.map(m=>`${m.role}: ${m.text}`).join('\n\n');const room=$('#debateRoom',view);room.innerHTML='<div class="l-ai-loading">🏆 AI Judge is evaluating both sides…</div>';try{const r=await ctx.AI.aiCall(`Act as an impartial debate and UPSC analytical-thinking judge. Evaluate this transcript. Return valid JSON only: {"scores":{"Logic":0,"Evidence":0,"Rebuttal":0,"Clarity":0,"Balance":0},"winner":"Student / AI / Balanced", "summary":"...", "improvement":"...", "factualCorrections":["..."]}. Scores are 0-10. Do not favour the AI. Transcript:\n${transcript}`,{json:true,maxTokens:1600,temperature:.2});d.judgement=ctx.AI.parseJsonLoose(r.text)||{summary:r.text,winner:'Assessment'};d.status='complete';ctx.save();renderDiscussion(view,ctx);}catch(e){room.innerHTML=`<div class="notice">${esc(e.message)}</div>`;}});
  $('#debateVoice',view)?.addEventListener('click',()=>dictate($('#debateArgument',view),$('#voiceStatus',view),ctx));
}
async function dictate(input,status,ctx){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){input?.focus();if(status)status.textContent='Speech recognition is unavailable here. Use your mobile keyboard microphone or press Win + H on Windows.';ctx.toast('Use keyboard voice typing / Windows Win + H for dictation.',5000);return;}try{if(navigator.mediaDevices?.getUserMedia){const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());}const rec=new SR();const lang=String(ctx.db.settings.tutorLang||'English').toLowerCase();rec.lang=lang.includes('hindi')||lang.includes('hinglish')?'hi-IN':'en-IN';rec.continuous=false;rec.interimResults=true;const base=input.value.trimEnd();let spoken='';rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const phrase=e.results[i][0]?.transcript||'';if(e.results[i].isFinal){spoken+=(spoken?' ':'')+phrase.trim();}else interim+=(interim?' ':'')+phrase;}input.value=base+(base&&spoken?' ':'')+spoken;if(status)status.textContent=interim?'Listening: '+interim:'Listening…';};rec.onerror=e=>{if(status)status.textContent=`Microphone: ${e.error}. You can use keyboard dictation instead.`;};rec.onend=()=>{if(status)status.textContent=spoken?'Dictation added to your argument.':'No speech captured. Try again or use keyboard dictation.';};if(status)status.textContent='Listening… speak now';rec.start();}catch(e){if(status)status.textContent='Microphone permission was not granted. Use keyboard dictation instead.';ctx.toast('Microphone permission is needed for voice input.',5000);}}

/* -------------------------------- CONTENT CREATOR -------------------------------- */
const OUTPUTS=[['notes','Structured chapter notes'],['facts','Important facts & data'],['mcq','MCQ question paper'],['mock','QUIZINOX-ready mock test'],['flashcards','Flashcards / active recall'],['statement','Statement-based questions'],['revision','Printable revision sheet'],['presentation','Educational presentation outline'],['worksheet','Printable practice worksheet']];
function renderCreator(view,ctx){const db=ctx.db;arrays(db);if(db.creatorSource)creatorSource=db.creatorSource;else db.creatorSource=creatorSource;const src=creatorSource; shell(view,'SOURCE-BASED GENERATION','QUIZINOX CONTENT CREATOR STUDIO','One source document → multiple educational outputs. Edit, regenerate and export each output independently; every item retains its source name.',`<button class="secondary" id="creatorClear">Clear source</button>`);view.innerHTML+=`<div class="l-creator-layout"><section class="panel"><div class="panel-head"><div><h3>① Upload or paste source</h3><p>PDF, TXT or plain text. PDF text is extracted on-device.</p></div></div><div class="l-source-row"><label class="secondary l-file-btn">⇧ Upload PDF / TXT<input type="file" id="creatorFile" accept=".pdf,.txt,.md,.text,application/pdf,text/plain" hidden/></label><span id="creatorSourceName">${esc(src.name)}</span></div><textarea id="creatorSource" rows="13" placeholder="Paste the chapter, study material or source text here…">${esc(src.text)}</textarea><div class="l-source-meta"><small>${src.text.length.toLocaleString()} characters · ${Math.ceil(src.text.length/4).toLocaleString()} estimated tokens</small><small>Source is kept with each generated output.</small></div></section><section class="panel"><div class="panel-head"><div><h3>② Select your output pipeline</h3><p>Choose multiple formats to generate from the same source.</p></div></div><div class="l-output-options">${OUTPUTS.map(([id,label])=>`<label><input type="checkbox" value="${id}" class="creator-output" ${['notes','facts','mcq','flashcards','statement','revision'].includes(id)?'checked':''}/><span><b>${label}</b><small>${id==='mcq'?'4-option MCQs with answer and explanation':id==='flashcards'?'Short recall prompts with answers':id==='statement'?'UPSC-style multi-statement MCQs':'Editable source-linked material'}</small></span></label>`).join('')}</div><div class="l-creator-quantities"><label>MCQ / Mock quantity<input type="number" id="creatorMcqCount" min="1" max="100" value="20"/></label><label>Flashcard quantity<input type="number" id="creatorFlashcardCount" min="1" max="100" value="30"/></label><label>Statement-question quantity<input type="number" id="creatorStatementCount" min="1" max="100" value="15"/></label></div><small class="muted">Large question/card sets are generated in smaller batches to reduce truncation. You can request up to 100 of each.</small><label>Extra instructions<textarea id="creatorInstructions" rows="3" placeholder="e.g. UPSC CSE standard, include examples, concise but complete…"></textarea></label><button class="primary full" id="creatorGenerate">✦ Generate selected outputs</button><small class="muted">AI requests run one after another, so provider/key rotation and free-tier pacing remain in effect.</small><div id="creatorProgress" class="l-creator-progress"></div></section></div><section class="panel l-generated"><div class="panel-head"><div><h3>③ Generated content library</h3><p>Each output can be edited, regenerated or exported separately.</p></div><span class="tag">${db.creatorOutputs.length} SAVED</span></div>${db.creatorOutputs.length?db.creatorOutputs.map(x=>`<article class="l-output-card"><div><span class="tag">${esc(x.kind)}</span><h3>${esc(x.title)}</h3><small>Source: ${esc(x.sourceName)} · ${new Date(x.createdAt).toLocaleString()}</small></div><textarea rows="8" data-output-content="${x.id}">${esc(x.content)}</textarea><div class="l-output-actions"><button class="secondary" data-output-save="${x.id}">Save edits</button>${x.quizId?`<button class="textbtn" data-output-openquiz="${x.quizId}">Open in My Quizzes ↗</button>`:''}<button class="textbtn" data-output-regen="${x.id}">↻ Regenerate</button><button class="textbtn" data-output-txt="${x.id}">⇩ TXT</button><button class="textbtn" data-output-html="${x.id}">⇩ HTML</button><button class="textbtn" data-output-pdf="${x.id}">⇩ PDF</button><button class="textbtn danger-text" data-output-del="${x.id}">Delete</button></div></article>`).join(''):'<div class="empty-mini"><b>No generated outputs yet</b><small>Upload a source, choose formats, and create your first content pipeline.</small></div>'}</section>`;
  $('#creatorSource',view).oninput=()=>{creatorSource.text=$('#creatorSource',view).value;db.creatorSource=creatorSource;};
  $('#creatorFile',view).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{creatorSource.name=f.name;creatorSource.text=(f.type==='application/pdf'||/\.pdf$/i.test(f.name))?await ctx.pdfText(f):await f.text();db.creatorSource=creatorSource;ctx.save();$('#creatorSource',view).value=creatorSource.text;$('#creatorSourceName',view).textContent=f.name;ctx.toast('Source loaded ✓');}catch(err){ctx.toast(err.message||'Could not read file',5000);}e.target.value='';};
  $('#creatorClear',view).onclick=()=>{creatorSource={name:'Pasted source',text:''};db.creatorSource=creatorSource;ctx.save();renderCreator(view,ctx);};
  $('#creatorGenerate',view).onclick=async()=>{creatorSource.text=$('#creatorSource',view).value;db.creatorSource=creatorSource;ctx.save();const source=creatorSource.text.trim();if(source.length<50)return ctx.toast('Add at least a few lines of source material');const kinds=$$('.creator-output:checked',view).map(x=>x.value);if(!kinds.length)return ctx.toast('Select at least one output');if(source.length>80000)return ctx.toast('This source is very large. Split it by chapter for higher accuracy.',5000);const progress=$('#creatorProgress',view),instructions=$('#creatorInstructions',view).value;const quantities={mcq:clampCount($('#creatorMcqCount',view).value,20),mock:clampCount($('#creatorMcqCount',view).value,20),flashcards:clampCount($('#creatorFlashcardCount',view).value,30),statement:clampCount($('#creatorStatementCount',view).value,15)};$('#creatorGenerate',view).disabled=true;for(let i=0;i<kinds.length;i++){const kind=kinds[i],title=OUTPUTS.find(x=>x[0]===kind)[1],quantity=quantities[kind]||null;progress.innerHTML=`<div class="l-creator-progress-bar"><i style="width:${Math.round(i/kinds.length*100)}%"></i></div><small>Generating ${i+1}/${kinds.length}: ${esc(title)}${quantity?` · ${quantity} items`:''}…</small>`;try{const content=await generateCreatorText(ctx,kind,source,instructions,quantity,(done,total)=>{progress.insertAdjacentHTML('beforeend',`<small>Batch ${done}/${total} completed…</small>`);});let quizId=null;if(kind==='mock'){const parsed=ctx.AI.parseJsonLoose(content),qs=normaliseCreatorQuestions(parsed?.questions);if(!qs.length)throw Error('Could not create a valid QUIZINOX mock. Regenerate this output or try a smaller count.');const quiz={id:uid(),title:`${creatorSource.name.replace(/\.[^.]+$/,'')} — AI Mock Test`,description:`Source-based mock created in Content Creator Studio from ${creatorSource.name}.`,subject:'AI Generated',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),settings:{timer:0,negative:0,shuffleQ:false,shuffleO:false,pass:40},questions:qs};db.quizzes.unshift(quiz);quizId=quiz.id;ctx.save();}addTo(db,'creatorOutputs',{id:uid(),kind,title,content,quantity,quizId,sourceName:creatorSource.name,sourceText:source,sourceHash:ctx.AI.hash(source),createdAt:new Date().toISOString()},ctx);progress.innerHTML+=`<small class="green-text">✓ ${esc(title)} created${quizId?' and added to My Quizzes':''}</small>`;}catch(e){progress.innerHTML+=`<small class="red-text">✕ ${esc(title)} — ${esc(e.message)}</small>`;}}$('#creatorGenerate',view).disabled=false;renderCreator(view,ctx);ctx.toast('Content pipeline finished');};
  $$('[data-output-save]',view).forEach(b=>b.onclick=()=>{const x=db.creatorOutputs.find(o=>o.id===b.dataset.outputSave);if(x){x.content=$(`[data-output-content="${x.id}"]`,view).value;x.updatedAt=new Date().toISOString();ctx.save();ctx.toast('Output edits saved ✓');}});
  $$('[data-output-openquiz]',view).forEach(b=>b.onclick=()=>ctx.setTab?.('quizzes'));
  $$('[data-output-regen]',view).forEach(b=>b.onclick=async()=>{const x=db.creatorOutputs.find(o=>o.id===b.dataset.outputRegen);if(!x)return;const source=x.sourceText||creatorSource.text||`Original source: ${x.sourceName}\nGenerated output: ${x.content}`;b.disabled=true;try{x.content=await generateCreatorText(ctx,x.kind,source,'Regenerate with improved structure and correctness. Preserve the source boundary.',x.quantity||null);if(x.kind==='mock'&&x.quizId){const q=db.quizzes.find(q=>q.id===x.quizId),parsed=ctx.AI.parseJsonLoose(x.content),qs=normaliseCreatorQuestions(parsed?.questions);if(q&&qs.length){q.questions=qs;q.updatedAt=new Date().toISOString();}}x.createdAt=new Date().toISOString();ctx.save();renderCreator(view,ctx);}catch(e){ctx.toast(e.message,5000);}finally{b.disabled=false;}});
  $$('[data-output-txt]',view).forEach(b=>b.onclick=()=>{const x=db.creatorOutputs.find(o=>o.id===b.dataset.outputTxt);ctx.saveFile(`${safeName(x.title)}.txt`,x.content,'text/plain');});
  $$('[data-output-html]',view).forEach(b=>b.onclick=()=>{const x=db.creatorOutputs.find(o=>o.id===b.dataset.outputHtml);const html=`<!doctype html><html><meta charset="utf-8"><title>${esc(x.title)}</title><body style="font:16px/1.65 system-ui;max-width:900px;margin:40px auto;padding:0 20px"><h1>${esc(x.title)}</h1><p>Source: ${esc(x.sourceName)}</p><pre style="white-space:pre-wrap;font:inherit">${esc(x.content)}</pre></body></html>`;ctx.saveFile(`${safeName(x.title)}.html`,html,'text/html');});
  $$('[data-output-pdf]',view).forEach(b=>b.onclick=async()=>{const x=db.creatorOutputs.find(o=>o.id===b.dataset.outputPdf);try{const {jsPDF}=await ctx.getJsPDF();const doc=new jsPDF();doc.setFontSize(18);doc.text(x.title,14,18);doc.setFontSize(9);doc.text(`Source: ${x.sourceName}`,14,26);doc.setFontSize(10);const lines=doc.splitTextToSize(x.content,180);let y=36;for(const line of lines){if(y>280){doc.addPage();y=18;}doc.text(line,14,y);y+=5;}await ctx.saveFile(`${safeName(x.title)}.pdf`,doc.output('blob'),'application/pdf');}catch(e){ctx.toast(e.message||'PDF export failed',5000);}});
  $$('[data-output-del]',view).forEach(b=>b.onclick=async()=>{if(!await ctx.confirmBox('Delete generated output?','This saved output will be removed.','Delete',true))return;db.creatorOutputs=db.creatorOutputs.filter(x=>x.id!==b.dataset.outputDel);ctx.save();renderCreator(view,ctx);});
}
function normaliseCreatorQuestions(items){return(Array.isArray(items)?items:[]).map(x=>{const options=Array.isArray(x.options)?x.options.slice(0,4).map(v=>String(v??'').trim()):[];const raw=x.correct??x.correctAnswer??x.answer;const letter=String(raw??'').trim().match(/^(?:option\s*)?([A-D])$/i);const correct=letter?letter[1].toUpperCase().charCodeAt(0)-65:Number(raw);const text=String(x.question||x.text||'').trim();if(!text||options.length!==4||options.some(v=>!v)||!Number.isInteger(correct)||correct<0||correct>3)return null;return{id:uid(),text,options,correct,explanation:String(x.explanation||''),topic:String(x.topic||'')};}).filter(Boolean);}
function clampCount(value,fallback){const n=Number(value);return Number.isFinite(n)?Math.max(1,Math.min(100,Math.floor(n))):fallback;}
function creatorPrompt(kind,source,instructions,quantity=null){const common=`Use ONLY the source below as the factual basis. Do not introduce unsupported facts. Preserve important dates, names, figures and qualifiers. If something is unclear, mark it as unclear instead of guessing. ${instructions||''}`;const task={notes:'Create well-structured chapter-wise study notes with headings, subheadings, definitions, examples and concise summaries.',facts:'Extract important facts, dates, data, names, constitutional articles, committees, cases and key terms. Keep each fact traceable to the source.',mcq:`Create exactly ${quantity||20} high-quality four-option MCQs from the source. Include question, exactly four options A-D, correct answer and a detailed explanation grounded in the source. Mix direct, conceptual and application questions.`,mock:`Return a valid JSON object only: {\"questions\":[{\"question\":\"...\",\"options\":[\"A...\",\"B...\",\"C...\",\"D...\"],\"correct\":0,\"explanation\":\"...\",\"topic\":\"...\"}]}. Generate exactly ${quantity||20} diverse, source-grounded MCQs for a QUIZINOX mock test. Each item must have exactly four non-empty options and correct must be an integer 0-3. Include a clear explanation.`,flashcards:`Create exactly ${quantity||30} concise active-recall flashcards. Each has a clear front/question and a short but complete back/answer. Keep every card source-based.`,statement:`Create exactly ${quantity||15} UPSC-style statement-analysis MCQs with 2-4 numbered statements, exactly four options, correct answer and a detailed explanation for each statement.`,revision:'Create a compact last-minute revision sheet with high-yield facts, concept links, common confusions and quick recall cues.',presentation:'Create a 10-slide educational presentation outline. For each slide include title, 3-5 key bullets, and a suggested visual or diagram.',worksheet:'Create a printable worksheet with 15 mixed question types, a clear answer key and explanations in a separate final section.'};return`${common}\nTASK: ${task[kind]}\nSOURCE DOCUMENT:\n${source}`;}
async function generateCreatorText(ctx,kind,source,instructions,quantity=null,onBatch=()=>{}){const batchSize=kind==='mcq'||kind==='mock'?10:kind==='statement'?5:kind==='flashcards'?10:quantity||1,total=quantity?Math.ceil(quantity/batchSize):1,parts=[],mockQuestions=[];for(let i=0;i<total;i++){const amount=quantity?Math.min(batchSize,quantity-i*batchSize):null;const batchNote=quantity?`Generate exactly ${amount} new items for batch ${i+1} of ${total}. Avoid repeating concepts or question stems within this batch. Include no placeholder items.`:'';const isMock=kind==='mock';const r=await ctx.AI.aiCall(creatorPrompt(kind,source,[instructions,batchNote].filter(Boolean).join(' '),amount),{json:isMock,maxTokens:isMock?3600:kind==='mcq'?3600:kind==='statement'?2600:kind==='flashcards'?1600:3600,temperature:.3});if(isMock){const data=ctx.AI.parseJsonLoose(r.text);mockQuestions.push(...normaliseCreatorQuestions(data?.questions));}else parts.push(r.text);onBatch(i+1,total);}if(kind==='mock'){if(!mockQuestions.length)throw Error('The AI did not return usable four-option questions. Try fewer questions or another provider.');if(quantity&&mockQuestions.length!==quantity)throw Error(`The AI returned ${mockQuestions.length} of ${quantity} requested questions. Regenerate this mock with a smaller count or another provider.`);return JSON.stringify({questions:mockQuestions},null,2);}return parts.join('\n\n');}
const safeName=s=>String(s||'quizinox').replace(/[^a-z0-9_-]+/gi,'_').slice(0,70);
